import { boxes } from "../targets/boxes.js";

// A target is any object with one method per step.
export const STEPS = ["build", "upload", "activate"];

export function deploy(args, log = console.log, target = boxes) {
  const dryRun = args.includes("--dry-run");
  checkTarget(target);

  for (const step of STEPS) {
    log(`-> ${step}`);
    if (!dryRun) {
      target[step]();
    }
  }

  log(dryRun ? "dry run: 3 steps skipped" : "deployed: 3 steps");
}

function checkTarget(target) {
  for (const step of STEPS) {
    if (typeof target[step] !== "function") {
      throw new Error(`target is missing step: ${step}`);
    }
  }
}
